FilePathOrError::FilePathOrError() : tag_(Tag::kError) {
  data_.error = ::drive::FileError();
}

FilePathOrError::~FilePathOrError() {
  DestroyActive();
}


void FilePathOrError::set_error(
    ::drive::FileError error) {
  if (tag_ != Tag::kError) {
    DestroyActive();
    tag_ = Tag::kError;
  }
  data_.error = error;
}
void FilePathOrError::set_path(
    const ::base::FilePath& path) {
  if (tag_ == Tag::kPath) {
    *(data_.path) = std::move(path);
  } else {
    DestroyActive();
    tag_ = Tag::kPath;
    data_.path = new ::base::FilePath(
        std::move(path));
  }
}

void FilePathOrError::DestroyActive() {
  switch (tag_) {

    case Tag::kError:

      break;
    case Tag::kPath:

      delete data_.path;
      break;
  }
}

bool FilePathOrError::Validate(
    const void* data,
    mojo::internal::ValidationContext* validation_context) {
  return Data_::Validate(data, validation_context, false);
}
const char DriveFsBootstrap::Name_[] = "drivefs.mojom.DriveFsBootstrap";

DriveFsBootstrap::IPCStableHashFunction DriveFsBootstrap::MessageToMethodInfo_(mojo::Message& message) {
#if !BUILDFLAG(IS_FUCHSIA)
  switch (message.name()) {
    case internal::kDriveFsBootstrap_Init_Name: {
      return &DriveFsBootstrap::Init_Sym::IPCStableHash;
    }
  }
#endif  // !BUILDFLAG(IS_FUCHSIA)
  return nullptr;
}


const char* DriveFsBootstrap::MessageToMethodName_(mojo::Message& message) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  bool is_response = message.has_flag(mojo::Message::kFlagIsResponse);
  if (!is_response) {
    switch (message.name()) {
      case internal::kDriveFsBootstrap_Init_Name:
            return "Receive drivefs::mojom::DriveFsBootstrap::Init";
    }
  } else {
    switch (message.name()) {
      case internal::kDriveFsBootstrap_Init_Name:
            return "Receive reply drivefs::mojom::DriveFsBootstrap::Init";
    }
  }
  return "Receive unknown mojo message";
#else
  bool is_response = message.has_flag(mojo::Message::kFlagIsResponse);
  if (is_response) {
    return "Receive mojo reply";
  } else {
    return "Receive mojo message";
  }
#endif // BUILDFLAG(MOJO_TRACE_ENABLED)
}

#if !BUILDFLAG(IS_FUCHSIA)
uint32_t DriveFsBootstrap::Init_Sym::IPCStableHash() {
  // This method's address is used for indetifiying the mojo method name after
  // symbolization. So each IPCStableHash should have a unique address.
  // We cannot use NO_CODE_FOLDING() here - it relies on the uniqueness of
  // __LINE__ value, which is not unique accross different mojo modules.
  // The code below is very similar to NO_CODE_FOLDING, but it uses a unique
  // hash instead of __LINE__.
  constexpr uint32_t kHash = base::MD5Hash32Constexpr(
          "(Impl)drivefs::mojom::DriveFsBootstrap::Init");
  const uint32_t hash = kHash;
  base::debug::Alias(&hash);
  return hash;
}
# endif // !BUILDFLAG(IS_FUCHSIA)

DriveFsBootstrapProxy::DriveFsBootstrapProxy(mojo::MessageReceiverWithResponder* receiver)
    : receiver_(receiver) {
}

void DriveFsBootstrapProxy::Init(
    DriveFsConfigurationPtr in_config, ::mojo::PendingReceiver<DriveFs> in_drive_fs, ::mojo::PendingRemote<DriveFsDelegate> in_delegate) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT1(
    "mojom", "Send drivefs::mojom::DriveFsBootstrap::Init", "input_parameters",
    [&](perfetto::TracedValue context){
      auto dict = std::move(context).WriteDictionary();
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("config"), in_config,
                        "<value of type DriveFsConfigurationPtr>");
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("drive_fs"), in_drive_fs,
                        "<value of type ::mojo::PendingReceiver<DriveFs>>");
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("delegate"), in_delegate,
                        "<value of type ::mojo::PendingRemote<DriveFsDelegate>>");
   });
#endif
  const bool kExpectsResponse = false;
  const bool kIsSync = false;
  const bool kAllowInterrupt = true;
  
  const uint32_t kFlags =
      ((kExpectsResponse) ? mojo::Message::kFlagExpectsResponse : 0) |
      ((kIsSync) ? mojo::Message::kFlagIsSync : 0) |
      ((kAllowInterrupt) ? 0 : mojo::Message::kFlagNoInterrupt);
  
  mojo::Message message(
      internal::kDriveFsBootstrap_Init_Name, kFlags, 0, 0, nullptr);
  mojo::internal::MessageFragment<
      ::drivefs::mojom::internal::DriveFsBootstrap_Init_Params_Data> params(
          message);
  params.Allocate();
  mojo::internal::MessageFragment<
      typename decltype(params->config)::BaseType> config_fragment(
          params.message());
  mojo::internal::Serialize<::drivefs::mojom::DriveFsConfigurationDataView>(
      in_config, config_fragment);
  params->config.Set(
      config_fragment.is_null() ? nullptr : config_fragment.data());
  MOJO_INTERNAL_DLOG_SERIALIZATION_WARNING(
      params->config.is_null(),
      mojo::internal::VALIDATION_ERROR_UNEXPECTED_NULL_POINTER,
      "null config in DriveFsBootstrap.Init request");
  mojo::internal::Serialize<mojo::InterfaceRequestDataView<::drivefs::mojom::DriveFsInterfaceBase>>(
      in_drive_fs, &params->drive_fs, &params.message());
  MOJO_INTERNAL_DLOG_SERIALIZATION_WARNING(
      !mojo::internal::IsHandleOrInterfaceValid(params->drive_fs),
      mojo::internal::VALIDATION_ERROR_UNEXPECTED_INVALID_HANDLE,
      "invalid drive_fs in DriveFsBootstrap.Init request");
  mojo::internal::Serialize<mojo::InterfacePtrDataView<::drivefs::mojom::DriveFsDelegateInterfaceBase>>(
      in_delegate, &params->delegate, &params.message());
  MOJO_INTERNAL_DLOG_SERIALIZATION_WARNING(
      !mojo::internal::IsHandleOrInterfaceValid(params->delegate),
      mojo::internal::VALIDATION_ERROR_UNEXPECTED_INVALID_HANDLE,
      "invalid delegate in DriveFsBootstrap.Init request");

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(DriveFsBootstrap::Name_);
  message.set_method_name("Init");
#endif
  // This return value may be ignored as false implies the Connector has
  // encountered an error, which will be visible through other means.
  ::mojo::internal::SendMojoMessage(*receiver_, message);
}

// static
bool DriveFsBootstrapStubDispatch::Accept(
    DriveFsBootstrap* impl,
    mojo::Message* message) {
  switch (message->header()->name) {
    case internal::kDriveFsBootstrap_Init_Name: {

      DCHECK(message->is_serialized());
      internal::DriveFsBootstrap_Init_Params_Data* params =
          reinterpret_cast<internal::DriveFsBootstrap_Init_Params_Data*>(
              message->mutable_payload());
      
      bool success = true;
      DriveFsConfigurationPtr p_config{};
      ::mojo::PendingReceiver<DriveFs> p_drive_fs{};
      ::mojo::PendingRemote<DriveFsDelegate> p_delegate{};
      DriveFsBootstrap_Init_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadConfig(&p_config))
        success = false;
      if (success) {
        p_drive_fs =
            input_data_view.TakeDriveFs<decltype(p_drive_fs)>();
      }
      if (success) {
        p_delegate =
            input_data_view.TakeDelegate<decltype(p_delegate)>();
      }
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            DriveFsBootstrap::Name_, 0, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->Init(
std::move(p_config), 
std::move(p_drive_fs), 
std::move(p_delegate));
      return true;
    }
  }
  return false;
}

