// static
bool UnionTraits<::drivefs::mojom::FilePathOrError::DataView, ::drivefs::mojom::FilePathOrErrorPtr>::Read(
    ::drivefs::mojom::FilePathOrError::DataView input,
    ::drivefs::mojom::FilePathOrErrorPtr* output) {
  using UnionType = ::drivefs::mojom::FilePathOrError;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kError: {
      ::drive::FileError result_error;
      if (!input.ReadError(&result_error))
        return false;

      *output = UnionType::NewError(result_error);
      break;
    }
    case Tag::kPath: {
      ::base::FilePath result_path;
      if (!input.ReadPath(&result_path))
        return false;

      *output = UnionType::NewPath(
          std::move(result_path));
      break;
    }
    default:

      return false;
  }
  return true;
}

